          hint: 'R1(config)# ip route 10.24.4.0 255.255.255.0 10.24.13.2 111\nR4(config)# ip route 10.24.1.0 255.255.255.0 10.24.34.1 111', ok: 'Nexthop: "Still an O in the table. The card\'s in the glovebox, waiting."',
